// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 amount, address target) public {
        vm.assume(caller != c.owner());
        vm.assume(amount <= address(this).balance);
        vm.deal(caller, amount);
        vm.prank(caller);
        bool ok = true;
        try c.sendMoney(target, amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "sendMoney should revert for non-owner caller");
    }
}
